from money import Money


def test_tolerant_parsing():
    assert Money(" 1.20 ").to_cents() == 120
    assert Money("$1,000.00").to_cents() == 100000


def test_half_up_rounding():
    assert Money("2.665").to_cents() == 267
    assert Money("2.645").to_cents() == 265


def test_thousands_separators_in_output():
    assert Money("1234.56").format() == "1,234.56"
